export type CheckoutDeliverySelectionResultResponseInput = { "data": (({ "audience": ("merchant") & ("merchant"); "checkout_session": CheckoutSessionInput; "delivery_selection": DeliverySelectionInput; "inventory_reservation"?: DeliveryInventoryReservationSummaryInput; "order": OrderInput; }) | ({ "audience": ("buyer") & ("buyer"); /** The checkout session after the change. Merchant-only fields, such as metadata and external_reference_id, are omitted. */ "checkout_session": { "active_payment_attempt"?: never; /** Contact the buyer entered in checkout before paying, saved with the session's checkout credential. Omitted until the buyer saves one. When a checkout session payment omits buyer_email or buyer_phone, Flint uses these values. Flint clears the contact 30 days after the session ends, and when a customer linked to the session is deleted. */ "buyer_contact"?: { /** Email the buyer entered, exactly as typed. Null when the buyer has not entered an email or cleared it. Format: email. maxLength: 255. */ "email": string | null; /** Phone the buyer entered, in E.164 format. Null when the buyer has not entered a phone or cleared it. pattern: ^\+[1-9][0-9]{1,14}$. */ "phone": string | null; /** When the buyer last changed the saved contact. Format: date-time. */ "updated_at"?: never; }; "checkout_session_id"?: never; /** Internal reason supplied when the checkout session was closed. This is not shown to the buyer. */ "closed_reason"?: never; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: never; "custom_text"?: CheckoutCustomTextWriteConfigInput; "customer"?: never; "customer_collection"?: CheckoutCustomerConfigInput; /** Contact and default addresses of the customer the checkout acts for: the customer the merchant created the session for, or the customer whose email the buyer confirmed in it. Present only on reads with the session's checkout credential while the session is open and acts for a customer. */ "customer_prefill"?: never; /** Immutable delivery method assignment captured when the checkout was created. */ "delivery_method_ids": Array<string>; /** Merchant-only immutable configuration lineage used to evaluate delivery quotes. */ "delivery_pinned_dependencies"?: never; /** Whether the order has at least one remaining quote-resolved fulfillment choice that must be selected before payment. */ "delivery_selection_required"?: never; "expiration"?: CheckoutExpirationConfigInput; /** RFC3339 timestamp. Format: date-time. */ "expires_at"?: never; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Current fulfillment choices for Flint-owned pricing. Checkout credentials receive the fields available to buyers; merchant credentials also receive configuration lineage and diagnostics. External pricing reports requires_explicit_quote; reading this field does not request a delivery quote. Omitted when the session is not open, has no order, or Flint cannot read its delivery. */ "fulfillment"?: never; "invoice"?: never; "invoice_id"?: never; "legal"?: LegalSettingsInput; "merchant_id"?: never; /** How the buyer can reach the merchant for help: the support email, phone, and URL the merchant set. Present only on reads with the session's checkout credential, and only when the merchant set at least one of them. Show it where your checkout tells the buyer to contact the merchant, such as an expired or closed checkout, or your receipt. */ "merchant_support"?: never; "metadata"?: Record<string, string>; "order"?: never; "order_id"?: string; "origin"?: never; "payment_collection"?: never; "payment_intent_ids"?: never; "payment_intents"?: never; "payment_link"?: never; "payment_link_id"?: never; /** The card the buyer saved with this checkout's payment by giving a mobile phone number, and whether they confirmed it. Present only on reads with the session's checkout credential, after a payment that paid the order in full, or that was approved for the merchant to capture later, and saved a card this way. A checkout whose payment is approved stays open until the capture. */ "payment_method_save"?: never; "payments"?: CheckoutPaymentConfigInput; "plan_id"?: never; /** Named conditions that affect checkout completion. Follow each problem's remediation action instead of reconstructing delivery lifecycle rules in the client. When Flint cannot read the checkout's delivery, the read still succeeds and reports delivery_selection_stale; its remediation says whether reading the session again can succeed, and its next action's reason_code names the error. */ "problems"?: never; "promotion_config"?: CheckoutPromotionConfigInput; /** RFC3339 deadline for the restricted payment-attempt recovery window. Format: date-time. */ "recovery_expires_at"?: never; /** Whether this terminal session credential is temporarily restricted to recovering its owning payment attempt. */ "recovery_mode"?: never; /** Payment attempt that this checkout credential may recover while recovery_mode is true. */ "recovery_payment_attempt_id"?: never; "redirects"?: CheckoutRedirectsConfigInput; /** Whether checkout offers the buyer the option to save the card they type for faster checkout at this merchant. Present only on reads with the session's checkout credential. When true and save_payment_method_requires_verification is false, PayOrder accepts save_payment_method: true for one newly collected card. False when the merchant turned checkout.saved_payment_details off, customer accounts are merchant hosted, card is not an available payment option, the checkout collects an invoice, a subscription, or a return, or the checkout acts for no customer and Flint cannot email the buyer a verification code. */ "save_payment_method_offered"?: never; /** Whether the buyer can save the card they type by giving a US or Canadian mobile phone number with the payment, in save_payment_method_phone on POST /v1/orders/{order_id}/pay, and confirming it with a texted code after paying. Present only on reads with the session's checkout credential. True while Flint can send texts and either save_payment_method_requires_verification is true, so the number replaces confirming an email before paying, or the checkout acts for the customer whose email the buyer confirmed with this credential, so the number joins that customer's saved details once the buyer confirms it. */ "save_payment_method_phone_offered"?: never; /** Whether the buyer must confirm their email with a code before the checkout can save their card or use their saved cards. Present only on reads with the session's checkout credential. True when save_payment_method_offered is true and the checkout acts for no customer for this credential: the merchant created it without one, and either the buyer has not confirmed an email with this credential, or the customer whose email they confirmed has since changed that email or been deleted. A credential other than the one a confirmation returned, such as the hosted checkout link opened on another device, reads true. Send the code with POST /v1/checkout-sessions/{checkout_session_id}/customer-verifications. False while the checkout acts for a customer, and whenever save_payment_method_offered is false. */ "save_payment_method_requires_verification"?: never; "setup_collection"?: never; "status"?: never; /** Renewal terms a subscription checkout commits the buyer to. Frozen when the session's order was created, so later plan changes do not alter them. Absent when the checkout starts no subscription. */ "subscription_terms"?: never; "superseding_checkout_session_id"?: never; "surface": "hosted" | "embedded"; "tax"?: CheckoutTaxConfigInput; "terminal_reason"?: never; "theme"?: ThemeConfigInput; "tip"?: CheckoutTipConfigInput; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: never; "url"?: never; }; "delivery_selection": BuyerDeliverySelectionInput; /** Omitted for checkout credentials, which cannot read the merchant's inventory reservation. Merchant credentials receive it on DeliverySelectionResult. */ "inventory_reservation"?: { /** RFC3339 timestamp. Format: date-time. */ "expires_at": string | globalThis.Date; "inventory_reservation_id": string; "owner_type": "delivery_selection" | "payment_attempt" | "order_balance_hold"; "required_next_action"?: "none" | "retry_payment" | "replace_selection" | "contact_merchant"; "status": "active" | "closed"; }; /** The order after the change. Merchant-only fields, such as external_reference_id and internal_note, are omitted. */ "order": { "active_payment_attempt"?: never; "applied_discounts"?: never; "authorization_amounts"?: never; /** What the buyer can do with the order, in this order: start_return, then resend_receipt. A buyer's read through a customer session on /v1/me, or in Flint's buyer account, lists both every time; a merchant read gets an empty list. A list of orders leaves start_return out, since only a read of one order checks return eligibility. start_return is due when the last open return window ends. Example: []. */ "buyer_actions"?: never; "buyer_email"?: never; "buyer_note"?: string; /** Phone the buyer gave when payment started, in E.164 format: the pay request's buyer_phone, or the phone saved on the paying checkout session. It does not change the linked customer. */ "buyer_phone"?: never; "charges"?: never; "checkout_session_ids"?: never; /** Internal reason supplied when the order was closed. This is not shown to the buyer. */ "closed_reason"?: never; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: never; "customer"?: never; "customer_id"?: string; /** The shipment or local-delivery destination committed for this order. Payment freezes this value; fulfillment recipient changes do not replace it. */ "delivery_destination"?: { "address": OrderDeliveryDestinationAddressInput; /** Delivery selection that controls this destination, when checkout collected it. */ "delivery_selection_id"?: string; /** Time payment froze this destination. Format: date-time. */ "frozen_at"?: string | globalThis.Date; "recipient"?: OrderDeliveryDestinationRecipientInput; "source": "delivery_selection" | "api" | "dashboard"; }; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "fulfillment_status"?: never; "fulfillments"?: never; "gift_card_estimate"?: never; "gift_card_settlements"?: never; "gift_card_tender_enabled"?: never; "gift_cards"?: never; "internal_note"?: string; "inventory_exception_status"?: never; /** The reservation holding stock for this order, when one exists. */ "inventory_reservation_id"?: never; /** Where this order's tracked demand is routed. Required before an order containing tracked variants can hold stock. */ "inventory_routing_source"?: { "inventory_allocation_policy_id"?: string; "inventory_allocation_policy_version_id"?: string; "location_id"?: string; "location_ids"?: Array<string>; "type": "fixed_location" | "policy" | "policy_version"; }; "line_items"?: never; "merchant_id"?: never; "metadata"?: Record<string, string>; "order_id"?: never; "order_number"?: never; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "order_revision"?: never; "origin"?: never; "payment_collection"?: never; "payment_intent_ids"?: never; "payment_intents"?: never; "payment_status"?: never; "plan_id"?: never; "pricing_amounts"?: never; "purchased_event"?: never; "refund_ids"?: never; "refund_status"?: never; "requested_tip"?: RequestedTipInput; "settlement_amounts"?: never; "setup_collection"?: never; "status"?: never; "subscription"?: never; "subscription_id"?: never; "subscription_plan"?: never; "tax"?: never; "tips"?: never; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: never; }; })); "meta"?: ResponseMetaInput; "request_id"?: string; };
